/**
 * Create the branch list, and spread the DEMO invoices across it.
 *
 * WHAT THIS IS ALLOWED TO INVENT, AND WHY THAT IS DIFFERENT FROM THE OTHER SCRIPTS
 *
 * `backfill-documents.mjs` refuses to invent a ticket number, because the PNRs it
 * migrates belong to real bookings and a fabricated document number would
 * reconcile against nothing. This script does invent, and the distinction is the
 * whole reason it is a separate file with a loud name.
 *
 * The 118 seeded invoices are not records of anything — `_meta.note` says
 * "Demo figures — generated by scripts/seed-accounting.mjs". Assigning a branch to
 * a synthetic sale is not falsifying history; the sale never happened. What it does
 * is make "profit by branch" demonstrable, which a report showing 98% unattributed
 * cannot be.
 *
 * The two storefront bookings are NOT touched here. They are real, they came from
 * the website, and the booking flow attributes them to the online branch itself.
 *
 *   node scripts/seed-attribution.mjs            # report only
 *   node scripts/seed-attribution.mjs --write    # do it
 *   node scripts/seed-attribution.mjs --branches-only --write   # branches, no spreading
 *
 * Re-runnable. An invoice that already has a branch is left alone, so running it
 * twice does not reshuffle attribution somebody set by hand.
 */
import { readFileSync, writeFileSync, mkdirSync, renameSync } from 'node:fs';
import path from 'node:path';

const BOOK = path.resolve('content/accounting.json');
const BACKUP_DIR = path.resolve('content/backups');
const write = process.argv.includes('--write');
const branchesOnly = process.argv.includes('--branches-only');

const book = JSON.parse(readFileSync(BOOK, 'utf8'));

/**
 * Three counters and the website. Plausible for a Dhaka agency of this size, and
 * the online one is load-bearing rather than decorative — the booking flow looks
 * for `kind: 'online'` to attribute a storefront sale.
 */
const BRANCHES = [
  { id: 'BR-001', name: 'Head office — Gulshan', city: 'Dhaka', kind: 'office', note: 'Main counter and corporate desk.' },
  { id: 'BR-002', name: 'Uttara counter', city: 'Dhaka', kind: 'office', note: 'Walk-in and Hajj enquiries.' },
  { id: 'BR-003', name: 'Chattogram counter', city: 'Chattogram', kind: 'office', note: 'Regional office.' },
  { id: 'BR-ONL', name: 'Online — storefront', city: '—', kind: 'online', note: 'Self-service bookings taken by the B2C portal. Attributed automatically.' }
];

book.branches = Array.isArray(book.branches) ? book.branches : [];
const existing = new Set(book.branches.map((b) => b.id));
const added = BRANCHES.filter((b) => !existing.has(b.id));

const consultants = (book.employees ?? []).filter((e) => /sales|reservation|manager/i.test(`${e.role} ${e.name}`));

/** Demo invoices only: seeded, and not already attributed by hand or by the portal. */
const isDemo = (inv) => !/storefront booking/i.test(inv.notes ?? '');
const targets = book.invoices.filter((i) => isDemo(i) && !i.branchId);
const alreadySet = book.invoices.filter((i) => i.branchId).length;
const realOnes = book.invoices.filter((i) => !isDemo(i)).length;

const offices = BRANCHES.filter((b) => b.kind === 'office');
const plan = targets.map((inv, i) => ({
  no: inv.no,
  // Deterministic round-robin rather than random: re-running produces the same
  // book, and a diff of the demo data stays readable.
  branchId: offices[i % offices.length].id,
  consultantId: consultants.length ? consultants[i % consultants.length].id : null
}));

console.log('');
console.log(`  branches to create      ${added.length} of ${BRANCHES.length}`);
console.log(`  demo invoices to spread ${plan.length}`);
console.log(`  already attributed      ${alreadySet}`);
console.log(`  real storefront sales   ${realOnes}  (left alone — the booking flow attributes those)`);
if (consultants.length) {
  console.log(`  consultants             ${consultants.map((c) => c.name).join(', ')}`);
} else {
  console.log('  consultants             none matched — invoices will get a branch but no consultant');
}

if (!write) {
  console.log('');
  console.log('  Report only — nothing was written. Re-run with --write to apply.');
  console.log('');
  process.exit(0);
}

mkdirSync(BACKUP_DIR, { recursive: true });
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backup = path.join(BACKUP_DIR, `accounting-before-attribution-${stamp}.json`);
writeFileSync(backup, readFileSync(BOOK, 'utf8'), 'utf8');

book.branches.push(...added);

if (!branchesOnly) {
  const byNo = new Map(plan.map((p) => [p.no, p]));
  for (const inv of book.invoices) {
    const p = byNo.get(inv.no);
    if (!p) continue;
    inv.branchId = p.branchId;
    inv.consultantId = p.consultantId;
  }
}

book._meta = {
  ...book._meta,
  revision: Number(book._meta?.revision ?? 0) + 1,
  lastEditedBy: 'scripts/seed-attribution.mjs',
  lastEditedAt: new Date().toISOString().slice(0, 19).replace('T', ' ')
};

const tmp = `${BOOK}.tmp`;
writeFileSync(tmp, JSON.stringify(book, null, 2), 'utf8');
renameSync(tmp, BOOK);

console.log('');
console.log(`  Backed up to ${path.relative(process.cwd(), backup)}`);
console.log(`  ${added.length} branch(es) created${branchesOnly ? '' : `, ${plan.length} demo invoice(s) attributed`}`);

/* --------------------------------------- attribution must not move a single total */
const appUrl = process.env.APP_URL || 'http://127.0.0.1:3002';
try {
  const res = await fetch(`${appUrl}/api/accounts/export?format=csv&section=reconciliation`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const rows = (await res.text()).trim().split(/\r?\n/).slice(1);
  const bad = rows.filter((r) => Number(r.split('","').map((c) => c.replace(/^"|"$/g, ''))[3]) !== 0);
  console.log('');
  console.log(`  Reconciliation: ${rows.length} account(s), ${bad.length} out of balance`);
  if (bad.length) {
    console.log('  THE BOOK MOVED. Attribution is a label on a sale and must change no total. Restore the backup.');
    for (const r of bad) console.log(`    ${r}`);
    process.exit(1);
  }
  console.log('  Nothing moved — attribution labels a sale, it does not reprice one.');
  console.log('');
} catch (err) {
  console.log('');
  console.log(`  Could not reach ${appUrl} to verify (${err.message}).`);
  console.log('');
}
